      height: 48px;
      margin-bottom: 22px;
      display: grid;
      place-items: center;
      border-radius: 18px;
      background: linear-gradient(135deg, rgba(138, 99, 255, .9), rgba(34, 211, 238, .85));
      box-shadow: 0 15px 32px rgba(34, 211, 238, 0.18);
    }

    .card h3 {
      font-size: 22px;
      margin-bottom: 12px;
    }

    .card p {
      color: var(--muted);
      line-height: 1.75;
    }

    .showcase {
      display: grid;
      grid-template-columns: 0.9fr 1.1fr;
      gap: 24px;
      align-items: stretch;
    }

    .quote {
      padding: 34px;
      border: 1px solid var(--line);
      border-radius: 34px;
      background: linear-gradient(135deg, rgba(138, 99, 255, 0.16), rgba(255, 255, 255, 0.07));
    }

    .quote p {
      color: #e8ecff;
      font-size: 24px;
      line-height: 1.55;
      letter-spacing: -0.02em;
    }

    .timeline {
      display: grid;
      gap: 14px;
    }

    .step {
      display: grid;
      grid-template-columns: auto 1fr;
      gap: 16px;
      padding: 20px;
      border: 1px solid var(--line);
      border-radius: 24px;
      background: rgba(255, 255, 255, 0.065);
    }

    .step b {
      width: 38px;
      height: 38px;
      display: grid;
      place-items: center;
      border-radius: 14px;
      background: rgba(34, 211, 238, 0.16);
      color: #91f4ff;
